// n8n must not trust its caller: check the batch before anything is written.
const b = $input.first().json.body ?? $input.first().json;
const errors = [];
if (typeof b.batchId !== 'string' || !/^[A-Za-z0-9._-]{1,80}$/.test(b.batchId)) errors.push('invalid batchId');
if (!Number.isInteger(b.index) || !Number.isInteger(b.total) || b.index < 1 || b.index > b.total) errors.push('invalid batch index');
if (!Array.isArray(b.columns) || b.columns.length === 0 || b.columns.length > 200) errors.push('invalid columns');
if (!Array.isArray(b.rows) || b.rows.length === 0 || b.rows.length > 1000) errors.push('a batch holds 1 to 1000 rows');
if (!Number.isInteger(b.offset) || b.offset < 0) errors.push('invalid offset');
if (errors.length) return [{ json: { ok: false, errors } }];
const source = String(b.source ?? '').slice(0, 180);
// One item per row. (batchId, row_index) is the key in Supabase, so a batch sent twice does not duplicate rows.
const rows = b.rows.map((data, i) => ({ batch_id: b.batchId, row_index: b.offset + i, source, data }));
return [{ json: { ok: true, batchId: b.batchId, index: b.index, total: b.total, count: rows.length, rows } }];
